script:
html { scroll-behavior: smooth; }
::selection { background: var(--d5f83a26-9c41-4e07-b812-6a4f2c9e3002, #201E1A); color: var(--d5f83a26-9c41-4e07-b812-6a4f2c9e3001, #F7F6F2); }
body { -webkit-font-smoothing: antialiased; }

.ra-link { transition: color 0.18s ease; }
.ra-link:hover { color: var(--d5f83a26-9c41-4e07-b812-6a4f2c9e3006, #3D5A45); }

img { filter: saturate(0.94); }
@media (prefers-color-scheme: dark) { img { filter: saturate(0.9) brightness(0.88); } }

a:focus-visible { border-radius: 4px; outline: 2px solid var(--d5f83a26-9c41-4e07-b812-6a4f2c9e3006, #3D5A45); outline-offset: 3px; }
